html:
{% set logo = doc.company_logo or "/assets/wafd_one/images/wafd-almadinah-new.png" %}
{% set signature = doc.signature_image %}
{% set stamp = doc.company_stamp %}
<style>
@page { size: A4; margin: 7mm 9mm 7mm 9mm; }
html, body, .print-format { margin:0!important; padding:0!important; background:#fff!important; }
.wafd-sheet {
  direction: rtl; position: relative; width:100%; min-height:276mm;
  box-sizing:border-box; padding:31mm 2mm 15mm 2mm;
  font-family: Tahoma, Arial, sans-serif; color:#111; background:#fff;
  font-size:10px; line-height:1.42; text-align:right;
}
.wafd-logo { position:absolute; top:0; right:0; width:25mm; height:31mm; object-fit:contain; }
.wafd-title { text-align:center; font-size:15px; font-weight:700; text-decoration:underline; margin:0 0 5mm; }
.meta { text-align:right; margin-bottom:1.2mm; }
p { margin:1.2mm 0; }
.party { margin:1.5mm 0; }
.party-title { font-weight:700; font-size:10.8px; }
.terms { margin:1.2mm 5mm 1.2mm 0; padding:0 5mm 0 0; }
.terms li { margin:.65mm 0; padding-right:1mm; }
.closing { margin-top:1.6mm; }
.sign-block { margin-top:3mm; text-align:center; page-break-inside:avoid; }
.sign-company { font-size:11.5px; font-weight:700; }
.sign-name { margin-top:1mm; font-size:10.5px; }
.sign-images { margin:1.5mm auto 0; width:90mm; height:24mm; position:relative; }
.signature-img { width:38mm; height:22mm; object-fit:contain; margin-left:5mm; }
.stamp-img { width:42mm; height:24mm; object-fit:contain; }
.placeholder { display:inline-block; width:36mm; height:18mm; vertical-align:middle; padding-top:8mm; border-bottom:1px solid #777; margin:0 3mm; color:#666; }
.footer { position:fixed; left:9mm; right:9mm; bottom:7mm; border-top:.35mm solid #b89a45; padding-top:2.2mm; text-align:center; font-size:8.7px; color:#3f3f3f; white-space:nowrap; }
.footer span { display:inline-block; margin:0 4mm; }
@media print {
  .wafd-sheet { page-break-inside:avoid!important; page-break-after:avoid!important; }
}
</style>
<div class="wafd-sheet">
  <img class="wafd-logo" src="{{ logo }}">
  <div class="wafd-title">تعهد والتزام إعاشة</div>

  <div class="meta">إنه في يوم - {{ doc.undertaking_date or '' }}</div>
  <p><b>الحمد لله، والصلاة والسلام على رسول الله، وبعد:</b></p>
  <p>فقد تم الاتفاق على هذا التعهد بين ؛</p>

  <div class="party">
    <div class="party-title">الطرف الأول:</div>
    {{ doc.company_name or 'شركة وفد المدينة لخدمات الإعاشة' }}<br>
    بموجب السجل التجاري رقم {{ doc.company_cr or '7051832694' }} ويمثلها السيد / {{ doc.company_representative or 'نزار نذير بن ظفر' }}
  </div>

  <div class="party">
    <div class="party-title">الطرف الثاني:</div>
    {{ doc.second_party_name or '' }}{% if doc.second_party_cr %} سجل تجاري رقم ( {{ doc.second_party_cr }} ){% endif %} ويشار إليها في هذا العقد بـ (الطرف الثاني)
  </div>

  <p><b>حيث اتفق الطرفان على الآتي:</b></p>
  <ol class="terms">
    <li>يقوم الطرف الأول بتأمين وجبات( {{ (doc.meal_types or 'الإفطار - الغداء - العشاء').replace('\n',' - ') }} ) لعدد ( {{ doc.beneficiary_count or '' }} ) حاج{% if doc.nationality %} من الجنسية {{ doc.nationality }}{% endif %}.</li>
    <li>موقع التوريد : {{ doc.supply_location or doc.hotel or '' }}</li>
    <li>مدة التعهد من تاريخ {{ doc.start_date or '' }}م وحتى {{ doc.end_date or '' }} م.</li>
    <li>يتعهد الطرفان بصحة البيانات المدونة أعلاه.</li>
    <li>يلتزم الطرفان بالمواعيد المحددة في تقديم الوجبات دون تأخير.</li>
    <li>يحق للطرف الأول المطالبة بإلغاء التعهد والمطالبة بالمبالغ المتبقية في حالة زيادة الأعداد أو اختلاف في البيانات المدونة، ولا يتم تعديل أي بند من القائمة أو جدول المواعيد.</li>
    <li>يلتزم الطرف الثاني بتأمين عمالة بشهادات صحية للتوريد للفندق.</li>
    <li>يجب على الفندق التدقيق والتأكد من صحة البيانات، وهي على مسؤولية الفندق في حالة عدم مطابقتها.</li>
    <li>يحق للفندق رفض التعهد في حالة عدم صحة البيانات للأعداد أو الأيام أو الجنسية.</li>
    <li>يلتزم الطرف الأول بتسليم الفندق صورة من الأوراق الرسمية من السجل، ورخصة البلدية، والعقد الخاص بالتغذية</li>
  </ol>

  <p class="closing">نأمل من إدارة الفندق التعاون والتواصل معنا بشكل مباشر في وجود أي ملاحظات ليتم تلافيها فورًا من قبلنا، وعرض هذا التعهد للجهات المسؤولة.</p>

  <div class="sign-block">
    <div class="sign-company">{{ doc.company_name or 'شركة وفد المدينة لخدمات الإعاشة' }}</div>
    <div class="sign-name">{{ doc.authorized_signatory or doc.company_representative or 'نزار نذير بن ظفر' }}</div>
    <div class="sign-images">
      {% if signature %}<img class="signature-img" src="{{ signature }}">{% else %}<span class="placeholder">التوقيع</span>{% endif %}
      {% if stamp %}<img class="stamp-img" src="{{ stamp }}">{% else %}<span class="placeholder">الختم</span>{% endif %}
    </div>
  </div>

  <div class="footer">
    <span>الجوال: {{ doc.company_phone or '0500336989' }}</span>
    <span>البريد الإلكتروني: {{ doc.company_email or 'wafd.almadinah@gmail.com' }}</span>
    <span>الموقع: مخطط الملك فهد - المدينة المنورة</span>
  </div>
</div>
